def grade(case, output):
    # 1) deterministic checks first
    if extract_amount(output) != case['expected_refund']:
        return {'pass': False, 'why': 'amount'}
    # 2) rubric LLM judge (different model, reasons before scoring)
    tone = judge(rubric=TONE_RUBRIC, answer=output)  # returns 1-5 or 'unknown'
    # 3) binary leakage classifier
    leak = leak_judge(output)                       # 'yes' / 'no'
    return {'pass': tone != 'unknown' and tone >= 4 and leak == 'no'}

msg = client.messages.create(model=MODEL, max_tokens=4096, messages=msgs)
if msg.stop_reason == 'max_tokens':
    log.warning('truncated', extra={'req': msg._request_id, 'out': msg.usage.output_tokens})
elif msg.stop_reason == 'refusal':
    route_to_human(msg)
else:
    data = parse(msg)
    errors = business_rules(data)   # sums, dates, cross-field checks
    if errors:
        retry_with_feedback(errors)  # specific errors, bounded retries
